<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true},download:{type:Function,required:true}})
const tabs=[['templates','卡片模板'],['codes','兑换码'],['usages','使用记录'],['statistics','统计']]
const tab=ref('templates'),templates=ref([]),codes=ref([]),usages=ref([]),types=ref({}),stats=ref(null),loading=ref(false),error=ref(''),modal=ref(false),saving=ref(false),formError=ref(''),page=ref(1),filterTemplate=ref(''),filterStatus=ref(''),batchFilter=ref(''),typesArray=computed(()=>Object.entries(types.value||{}))
const form=reactive({id:null,name:'',description:'',type:1,status:true,conditions:'{}',rewards:'{}',limits:'{}',special_config:'{}',icon:'',background_image:'',theme_color:'#16866f',sort:0})
const gen=reactive({template_id:'',count:10,prefix:'GC',expires_hours:'',max_usage:1,download_csv:true})
const codeEdit=reactive({id:null,expires_at:'',max_usage:1,status:0})
const codeModal=ref(false)
const when=v=>v?new Date(Number(v)*1000).toLocaleString('zh-CN'):'长期有效'
async function load(){loading.value=true;error.value='';try{types.value=await props.api('gift-card/types');if(tab.value==='templates'||!templates.value.length){const t=await props.api(`gift-card/templates?page=${page.value}&per_page=25`);templates.value=Array.isArray(t)?t:[]}if(tab.value==='templates'){}else if(tab.value==='codes'){const q=new URLSearchParams({page:String(page.value),per_page:'25'});if(filterTemplate.value)q.set('template_id',filterTemplate.value);if(filterStatus.value!=='')q.set('status',filterStatus.value);if(batchFilter.value)q.set('batch_id',batchFilter.value);const r=await props.api(`gift-card/codes?${q}`);codes.value=Array.isArray(r)?r:[]}else if(tab.value==='usages'){const q=new URLSearchParams({page:String(page.value),per_page:'25'});if(filterTemplate.value)q.set('template_id',filterTemplate.value);const r=await props.api(`gift-card/usages?${q}`);usages.value=Array.isArray(r)?r:[]}else stats.value=await props.api('gift-card/statistics')}catch(e){error.value=e.message}finally{loading.value=false}}
function changeTab(id){tab.value=id;page.value=1;load()}
function emptyTemplate(){Object.assign(form,{id:null,name:'',description:'',type:1,status:true,conditions:'{}',rewards:'{}',limits:'{}',special_config:'{}',icon:'',background_image:'',theme_color:'#16866f',sort:0});formError.value=''}
function createTemplate(){emptyTemplate();modal.value=true}
function editTemplate(t){emptyTemplate();Object.assign(form,{id:t.id,name:t.name,description:t.description||'',type:Number(t.type),status:Boolean(t.status),conditions:JSON.stringify(t.conditions||{},null,2),rewards:JSON.stringify(t.rewards||{},null,2),limits:JSON.stringify(t.limits||{},null,2),special_config:JSON.stringify(t.special_config||{},null,2),icon:t.icon||'',background_image:t.background_image||'',theme_color:t.theme_color||'#16866f',sort:Number(t.sort||0)});modal.value=true}
const parseJson=(text,label)=>{try{return JSON.parse(text||'{}')}catch{throw new Error(`${label} JSON 格式无效。`)}}
async function saveTemplate(){saving.value=true;formError.value='';try{const body={name:form.name,description:form.description||null,type:Number(form.type),status:form.status,conditions:parseJson(form.conditions,'conditions'),rewards:parseJson(form.rewards,'rewards'),limits:parseJson(form.limits,'limits'),special_config:parseJson(form.special_config,'special_config'),icon:form.icon||null,background_image:form.background_image||null,theme_color:form.theme_color,sort:Number(form.sort||0)};await props.api(form.id?'gift-card/update-template':'gift-card/create-template',{method:'POST',body:form.id?{id:form.id,...body}:body});modal.value=false;await load()}catch(e){formError.value=e.message}finally{saving.value=false}}
async function deleteTemplate(t){if(!window.confirm(`删除模板“${t.name}”？若已生成兑换码，后端会拒绝删除。`))return;try{await props.api('gift-card/delete-template',{method:'POST',body:{id:t.id}});await load()}catch(e){error.value=e.message}}
async function generateCodes(){saving.value=true;formError.value='';try{const body={template_id:Number(gen.template_id),count:Number(gen.count),prefix:gen.prefix||'GC',max_usage:Number(gen.max_usage||1),download_csv:Boolean(gen.download_csv)};if(gen.expires_hours)body.expires_hours=Number(gen.expires_hours);if(gen.download_csv){await props.download('gift-card/generate-codes',{method:'POST',body},'gift-codes.csv')}else{const result=await props.api('gift-card/generate-codes',{method:'POST',body});if(result?.batch_id)batchFilter.value=result.batch_id}tab.value='codes';page.value=1;await load()}catch(e){formError.value=e.message}finally{saving.value=false}}
async function toggleCode(c){try{await props.api('gift-card/toggle-code',{method:'POST',body:{id:c.id,action:Number(c.status)===3?'enable':'disable'}});await load()}catch(e){error.value=e.message}}
function editCode(c){Object.assign(codeEdit,{id:c.id,expires_at:c.expires_at?new Date(Number(c.expires_at)*1000).toISOString().slice(0,16):'',max_usage:Number(c.max_usage||1),status:Number(c.status)});codeModal.value=true}
async function saveCode(){saving.value=true;try{await props.api('gift-card/update-code',{method:'POST',body:{id:codeEdit.id,expires_at:codeEdit.expires_at?Math.floor(new Date(codeEdit.expires_at).getTime()/1000):null,max_usage:Number(codeEdit.max_usage),status:Number(codeEdit.status)}});codeModal.value=false;await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function deleteCode(c){if(!window.confirm(`删除兑换码 ${c.code}？`))return;try{await props.api('gift-card/delete-code',{method:'POST',body:{id:c.id}});await load()}catch(e){error.value=e.message}}
async function exportBatch(){if(!batchFilter.value)return;try{await props.download(`gift-card/export-codes?batch_id=${encodeURIComponent(batchFilter.value)}`)}catch(e){error.value=e.message}}
onMounted(()=>load())
</script>
<template><section class="content-view gift-view"><div class="page-title-row"><div><p class="eyebrow">CUSTOMERS / REWARDS</p><h1>礼品卡<span class="title-period">.</span></h1><p class="page-subtitle">模板、批量兑换码、使用记录与统计</p></div><button v-if="tab==='templates'" class="assign-order-button" @click="createTemplate">＋ 新建模板</button></div><div class="gift-tabs"><button v-for="[id,name] in tabs" :key="id" :class="{selected:tab===id}" @click="changeTab(id)">{{name}}</button></div><div v-if="error" class="api-error"><span>!</span><div><b>礼品卡请求失败</b><p>{{error}}</p></div><button @click="load">重试</button></div>
<div v-if="tab==='templates'"><div class="users-table-wrap"><div v-if="loading" class="table-state">正在读取模板…</div><div v-else-if="!templates.length" class="table-state">暂无礼品卡模板。</div><table v-else class="users-table gift-table"><thead><tr><th>模板</th><th>类型</th><th>奖励</th><th>兑换码 / 使用</th><th>状态</th><th>排序</th><th>操作</th></tr></thead><tbody><tr v-for="t in templates" :key="t.id"><td><b>{{t.name}}</b><small class="order-id">ID {{t.id}} · {{t.description||'无描述'}}</small></td><td>{{t.type_name||types[t.type]||t.type}}</td><td><code class="trade-code">{{JSON.stringify(t.rewards)}}</code></td><td>{{t.codes_count}} / {{t.used_count}}</td><td><span class="user-status" :class="{disabled:!t.status}">{{t.status?'启用':'停用'}}</span></td><td>{{t.sort}}</td><td><div class="row-actions"><button @click="editTemplate(t)">编辑</button><button class="danger-action" @click="deleteTemplate(t)">删除</button></div></td></tr></tbody></table></div><div class="gift-generator"><div><p class="eyebrow">CODE BATCH / GENERATE</p><h2>批量生成兑换码</h2><p>生成后可直接下载 CSV，也可在兑换码页查看批次。</p></div><form class="gift-generate-form" @submit.prevent="generateCodes"><select v-model="gen.template_id" required><option disabled value="">选择模板</option><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}} · {{t.id}}</option></select><input v-model.number="gen.count" type="number" min="1" max="10000" aria-label="生成数量"/><input v-model="gen.prefix" maxlength="10" placeholder="GC 前缀" aria-label="兑换码前缀"/><label><input v-model="gen.download_csv" type="checkbox"/>下载 CSV</label><button class="save-button" :disabled="saving">{{saving?'生成中…':'生成'}}</button></form><p v-if="formError" class="notice">{{formError}}</p></div></div>
<div v-else-if="tab==='codes'"><div class="gift-filter"><select v-model="filterTemplate" @change="load(1)"><option value="">全部模板</option><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name}}</option></select><select v-model="filterStatus" @change="load(1)"><option value="">全部状态</option><option value="0">未使用</option><option value="1">已使用</option><option value="2">已过期</option><option value="3">已禁用</option></select><input v-model="batchFilter" placeholder="按批次号筛选"/><button @click="load(1)">筛选</button><button :disabled="!batchFilter" @click="exportBatch">导出批次</button></div><div class="users-table-wrap"><div v-if="loading" class="table-state">正在读取兑换码…</div><div v-else-if="!codes.length" class="table-state">暂无兑换码。</div><table v-else class="users-table gift-table"><thead><tr><th>兑换码</th><th>模板</th><th>批次</th><th>状态</th><th>使用者</th><th>有效期</th><th>操作</th></tr></thead><tbody><tr v-for="c in codes" :key="c.id"><td><code class="trade-code">{{c.code}}</code></td><td>{{c.template_name}}</td><td><code class="trade-code">{{c.batch_id}}</code></td><td>{{c.status_name}}</td><td>{{c.user_email||'—'}}</td><td>{{when(c.expires_at)}}</td><td><div class="row-actions"><button @click="toggleCode(c)">{{Number(c.status)===3?'启用':'禁用'}}</button><button @click="editCode(c)">编辑</button><button class="danger-action" @click="deleteCode(c)">删除</button></div></td></tr></tbody></table></div></div>
<div v-else-if="tab==='usages'" class="users-table-wrap"><div v-if="loading" class="table-state">正在读取使用记录…</div><div v-else-if="!usages.length" class="table-state">暂无使用记录。</div><table v-else class="users-table gift-table"><thead><tr><th>兑换码</th><th>模板</th><th>用户</th><th>奖励</th><th>使用时间</th></tr></thead><tbody><tr v-for="u in usages" :key="u.id"><td><code class="trade-code">{{u.code}}</code></td><td>{{u.template_name}}</td><td>{{u.user_email}}</td><td><code>{{JSON.stringify(u.rewards_given)}}</code></td><td>{{when(u.created_at)}}</td></tr></tbody></table></div>
<div v-else-if="tab==='statistics'" class="gift-stat-grid"><article v-for="(value,key) in stats?.total_stats||{}" :key="key" class="metric-card"><div class="metric-top">{{key}}</div><div class="metric-value">{{value}}</div></article><article class="data-panel"><h2>每日使用统计</h2><pre class="response-json">{{JSON.stringify(stats?.daily_usages||[],null,2)}}</pre></article><article class="data-panel"><h2>类型统计</h2><pre class="response-json">{{JSON.stringify(stats?.type_stats||[],null,2)}}</pre></article></div>
<div v-if="['codes','usages'].includes(tab)" class="table-pagination"><span>第 {{page}} 页 · 当前页 {{tab==='codes'?codes.length:usages.length}} 条</span><div><button :disabled="page<=1||loading" @click="page--;load()">← 上一页</button><button :disabled="(tab==='codes'?codes.length:usages.length)<15||loading" @click="page++;load()">下一页 →</button></div></div><div v-if="tab==='templates'" class="table-pagination"><span>第 {{page}} 页 · {{templates.length}} 个模板</span><div><button :disabled="page<=1||loading" @click="page--;load()">← 上一页</button><button :disabled="templates.length<25||loading" @click="page++;load()">下一页 →</button></div></div><div class="footer-note"><span>XB CONTROL ROOM</span><span>礼品卡奖励为 JSON 结构 <i>·</i> 生成兑换码会写入 Xboard</span></div>
<div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="user-modal gift-modal" role="dialog" aria-modal="true"><header class="modal-header"><div><p class="eyebrow">GIFT CARD / TEMPLATE</p><h2>{{form.id?'编辑模板':'新建模板'}}</h2></div><button class="modal-close" @click="modal=false">×</button></header><form class="user-form" @submit.prevent="saveTemplate"><label>模板名称<input v-model.trim="form.name" required/></label><label>描述<textarea v-model="form.description" rows="2"/></label><div class="form-pair"><label>礼品卡类型<select v-model.number="form.type"><option v-for="[id,name] in typesArray" :key="id" :value="Number(id)">{{name}}</option></select></label><label>主题色<input v-model="form.theme_color" type="color"/></label></div><label>奖励配置 JSON<textarea v-model="form.rewards" rows="6" required spellcheck="false"/></label><div class="form-pair"><label>使用条件 JSON<textarea v-model="form.conditions" rows="4" spellcheck="false"/></label><label>使用限制 JSON<textarea v-model="form.limits" rows="4" spellcheck="false"/></label></div><label>特殊配置 JSON<textarea v-model="form.special_config" rows="4" spellcheck="false"/></label><label>背景图片 URL<input v-model.trim="form.background_image" type="url"/></label><div class="toggle-row"><label><input v-model="form.status" type="checkbox"/> 启用模板</label></div><p v-if="formError" class="notice">{{formError}}</p><footer class="modal-footer"><button type="button" class="cancel-button" @click="modal=false">取消</button><button class="save-button" :disabled="saving">{{saving?'保存中…':'保存模板'}}</button></footer></form></section></div>
<div v-if="codeModal" class="modal-backdrop" @click.self="codeModal=false"><section class="user-modal"><header class="modal-header"><h2>编辑兑换码</h2><button class="modal-close" @click="codeModal=false">×</button></header><form class="user-form" @submit.prevent="saveCode"><label>有效期<input v-model="codeEdit.expires_at" type="datetime-local"/></label><label>最大使用次数<input v-model.number="codeEdit.max_usage" type="number" min="1" max="1000"/></label><label>状态<select v-model.number="codeEdit.status"><option :value="0">未使用</option><option :value="3">禁用</option></select></label><footer class="modal-footer"><button type="button" class="cancel-button" @click="codeModal=false">取消</button><button class="save-button" :disabled="saving">保存</button></footer></form></section></div>
</section></template>
